#!/bin/sh
# SPDX-License-Identifier: GPL-2.0-or-later
#
# Builds the idevice FFI static library as an xcframework for the iOS device,
# so Andarium's built-in JIT can reach the device's own debugserver through a
# paired tunnel. idevice is https://github.com/jkcoxson/idevice (MIT); the
# pinned commit is in idevice.pin beside this script. The build needs a Mac
# with Xcode and a Rust toolchain that has the aarch64-apple-ios target.
#
# Output: $OUT/IDevice.xcframework and the matching idevice.h header. The
# Andarium project links the static library and imports idevice.h through its
# bridging header. Only the iOS device slice is built, because the built-in
# JIT exists on a real device alone.
set -eu

HERE=$(cd "$(dirname "$0")" && pwd)
PIN=$(cat "$HERE/idevice.pin")
OUT=${OUT:-"$HERE/.build"}
SRC=${IDEVICE_SRC:-"$OUT/src"}
# The idevice FFI features the built-in JIT needs: a paired tunnel to the
# device's RemoteServiceDiscovery, the debug proxy, and a heartbeat to hold
# the tunnel open while a region is blessed.
FEATURES=${IDEVICE_FEATURES:-"tunnel_tcp_stack,debug_proxy,heartbeat,core_device,ring"}

log() { printf 'idevice: %s\n' "$*" >&2; }

command -v cargo >/dev/null 2>&1 || { log "cargo (Rust) is required"; exit 1; }
command -v xcodebuild >/dev/null 2>&1 || { log "xcodebuild is required"; exit 1; }

if [ ! -d "$SRC/.git" ]; then
	log "cloning idevice $PIN"
	rm -rf "$SRC"
	git clone --no-checkout https://github.com/jkcoxson/idevice "$SRC"
	git -C "$SRC" fetch --depth 1 origin "$PIN"
	git -C "$SRC" checkout -q "$PIN"
fi

rustup target add aarch64-apple-ios 2>/dev/null || true

log "building for aarch64-apple-ios"
(
	cd "$SRC/ffi"
	BINDGEN_EXTRA_CLANG_ARGS="--sysroot=$(xcrun --sdk iphoneos --show-sdk-path)" \
		IPHONEOS_DEPLOYMENT_TARGET=17.0 \
		cargo build --release --target aarch64-apple-ios \
		--no-default-features --features "$FEATURES"
)

LIB="$SRC/target/aarch64-apple-ios/release/libidevice_ffi.a"
[ -f "$LIB" ] || { log "static library was not produced at $LIB"; exit 1; }

# The checked-in header is generated by the FFI build; refresh it so the
# vendored copy matches the pinned source exactly, and re-add the SPDX line the
# repository's licence-header rule needs (idevice is MIT; the generated header
# carries no SPDX line of its own).
{
	printf '// SPDX-License-Identifier: MIT\n'
	cat "$SRC/ffi/idevice.h"
} > "$HERE/idevice.h"

INCLUDE="$OUT/include"
rm -rf "$INCLUDE"
mkdir -p "$INCLUDE"
cp "$HERE/idevice.h" "$INCLUDE/idevice.h"

rm -rf "$OUT/IDevice.xcframework"
xcodebuild -create-xcframework \
	-library "$LIB" -headers "$INCLUDE" \
	-output "$OUT/IDevice.xcframework"

log "built $OUT/IDevice.xcframework"
